questions.code_template:
.center {
  display: flex;
  justify-content: center;
  _____: center;
  min-height: 100vh;
}

questions.code:
.dashboard {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  grid-auto-rows: minmax(150px, auto);
  gap: 24px;
}

.widget-wide {
  grid-column: span 2;
}

.widget-full {
  grid-column: 1 / -1;
}
